  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (553::BIGINT, 'Aparenta ser simpática y energética, pero puede hace comentarios humillantes o sarcáticos. Tambien tiene a sus favoritos.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-20T00:00:00+00:00'::TIMESTAMPTZ, '4680a2412bbed3ccc1b1bed04cd00d93795f03a96b41e2c3a3f43958db178759'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Es un curso pesado pero la profe explica todo bastante claro. Los quizzes ayudan mucho para los exámenes y hay puntos extra. La profe es buena nota y califica justo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-02-04T00:00:00+00:00'::TIMESTAMPTZ, '585721675d87aa210a3517973eab39f24c0f75c9a48d80111964fd67712a290f'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (553::BIGINT, 'Sin duda alguna una increíble profesora, explica demasiado claro, los quices ayudan muchísimo, al principio tenía miedo de matricular con ella, pero sin duda es lo mejor que pude hacer, no solo hace que uno entienda y pueda analizar las cosas, sino que hace el curso muy ameno. ¡Matriculen con ella!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2026-01-30T00:00:00+00:00'::TIMESTAMPTZ, '125b3189f0f095a1e85ad95a51caef9d7442651f064555a4a03fc3bf1f76cf66'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Es una profesora excelente, muestra mucho entusiasmo a la hora de explicar y eso hace que uno tenga más interés en el curso. Hace presentaciones completas y explica muy claro, sus quizzes ayudan bastante para la preparación de los examenes y siempre se preocupa de que todos estén entendiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-12-23T00:00:00+00:00'::TIMESTAMPTZ, '10a8a17c5dd3c32c64b75095d3f0c49a2d0914c67e644cc1ee0778b0a0d9ab44'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Super profe. Es estricta, pero explica excelente y sus presentaciones son muy claras para repasar. Con sus prácticas vas súper preparado al examen, y hay que dedicar tiempo, pero ella es muy accesible y paciente. Le gusta que muestren interés'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Clases excelentes']::TEXT[], '2025-12-10T00:00:00+00:00'::TIMESTAMPTZ, '4ec270ff878e4b923ea798e0493a61d6730b5a0b802e9911138ce59c178f1368'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Lo lleve en verano y se me hizo demasiado pesado el curso es de ponerle bastante porque si ayuda si se lo piden y explica bien, pero es bastante dura'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-11-06T00:00:00+00:00'::TIMESTAMPTZ, 'b8aad6efa0b8f6d2a4e73a9a1e6e95e7501fb36b4e20ff411efb78828b56e681'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Deja trabajos para regalar porcentaje extra. También hace quices con ejercicios de examen que aunque sean duros ayudan a prepararse, es muy amable pero también estricta con ciertas cosas como no dormirse en clases, da mucho material de apoyo para los que son más autodidactos.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2025-08-11T00:00:00+00:00'::TIMESTAMPTZ, 'd1b2b1b6ef65c9ce2d655ad2360dbeeae34c818ed69110aeca85d178d6c955d8'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Tiene demasiados grupos, está en todo y no está en nada entonces se ataranta y da la materia muy rápido para entender. Es pasivo-agresiva y condescendiente, hace comentarios que lo hacen sentir mal a uno y lo desmotivan. No recomiendo llevar nada con ella, uno sale de cada clase hasta enojado.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'ba2027a84f98ab2c6e07ca274f4babf9ff2745f9be29009925c1cd384692a0d0'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'En ocasiones puede ser condescendiente, da muchas posibilidades para ganar puntos extra, el curso es sencillo. No se tome nada personal y dele sin miedo :)'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, '17b5de3bb93c68f59cb1f58857abce5c7c46ab7ac0667351069f68a8bf8785be'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (553::BIGINT, 'A pesar de los comentarios no fue así, nos ayudó a pasar los que llegamos a repo, dió quices extra para aumentar la nota, y practicamente eran regalos. Eso si, póngase las pilas, le gusta la puntualidad y el ser aplicado. La recomiendo, muy buena persona y profe :)'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-03T00:00:00+00:00'::TIMESTAMPTZ, '05c726608e42d7fe9c90ff1ac03eddd4e73f95f23ff2f2ae4b2ab894f307e75d'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (553::BIGINT, 'Es la profesora mas apestos+ de todo el tec, si solo queda ella, desaproveche la oportunidad, es una mala profesora, mala persona, mala todo, no espere que le tenga empatia, ni para explicar, es demasiado odiosa y trata a todos como si fueran retrasados'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2025-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'd298fdb65734f5dcded2a6207972beab6e34fdf0b16f1a606d70471571884f6d'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'La profe se esfuerza en que el estudiante aprenda, hace presentaciones con toda la información, hace practicas para el examen y los quices lo preparan para los exámenes. Es exigente pero bueno, es el tec que esperaban.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo']::TEXT[], '2025-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'af7ff739676691e60649e2f3bb2b179c1d41c629250d452358f7e388f89caeae'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Los comentarios que ella tiene la verdad no los comparto, sentí que fue una persona que verdaderamente la pulseo este semestre para que uno entienda, si usted pone de su parte y estudia sus clases tal cual, pasa con 100%, matriculen sin miedo, que hay profesores mil veces peores, acostúmbrense.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Inspirador']::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, '9b7b0fd899a013a2c4a49570749c966919feaf75dc3e853bf6ca4064d2ca098c'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (553::BIGINT, 'Matricule con otra persona, califica demasiado duro y hace unos quizes horribles. Ella dice que ayuda al estudiante pero uno le escribe y literalmente lo manda a la porra con comentarios pasivo agresivos, es sarcástica y pesada en ciertas ocasiones. No la recomiendo si quiere pasar y aprender algo'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2025-06-23T00:00:00+00:00'::TIMESTAMPTZ, '3e5fd8c9e49a140d750980e868847bf432411e55cd579f06486f5cc483a80c53'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (553::BIGINT, 'Es muy condescendiente, lo tarta mal a uno si le pregunta sobre la materia unas semanas después que la da, hace muchos quices. Lo trata a uno mal en los exámenes, en persona se intenta hacer la amable, per hace comentarios pasivo agresivos. Ir a consulta le deja mas enredo de como llego.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes', 'Deja trabajos largos']::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, '4892b32806f0de909167ddfe9dc1bf35fb9bf7052181c4f83123502f4302425a'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'La profe es muy amable e intenta ayudar a los estudiantes, suele hacer muchos quizes para puntos extra y se ve que le gusta mucho la materia que enseña, se emociona mucho en sus clases. Le gusta que sus estudiantes se interesen por la materia y no tiene problemas en volver a explicar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'f350f38c8a5b06f273a4a9154c15d7e693c3be49fce2873cf3d6438e831c2f39'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (553::BIGINT, 'Hace los exámenes muy parecidos a los semestres pasados, la clase se puede hacer un poco cansada y hace quices casi que todos los días, pero ayuda a llevar toda la materia al día.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-11T00:00:00+00:00'::TIMESTAMPTZ, '0b27ede3d4fffbad02f978c8d6669d2af0df09f7c488ed500f1305456ce30d2e'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Sea responsable y respetuoso, no le gusta la mediocridad. Puede ser grosera pero yendo a consulta se sabe que la disposición a ayudar y su entendimiento mejora significativamente.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'a9db5811c7c7fe1182896476044eea0e1d5889fa49e1c6815ae0d7f22226e26a'::TEXT, ARRAY[613]::BIGINT[]),
    (553::BIGINT, 'Sus "sugerencias" son desde una perspectiva de superioridad, cuando usted pregunta lo humilla y lo regaña. En los quizzes mete materia que pasó muy por encima. No explica para nada bien y se le pasan detalles por encima. Si quiere pasar el curso ella no es una opción 0/10'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, '8a23147df51ad808a2ff377753312efc6cc2e740d981f5aaa6943f78f4a28093'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (553::BIGINT, 'Es una buena profesora en realidad, pero debe estudiar bastante, con los exámenes del 2019 es suficiente para salir bien en los quizzes y los exámenes, ayuda mucho en consulta, además es la coordinadora actual.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Muchos exámenes']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, '5cef0aa4f27fb0e5ecb24bfe9fee08d15494e4c96865484998b333b5e51c91fc'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Por qué razón tienen a una persona como esa dando clases, es arrogante, es mala profesora, grosera, temperamental, con complejo de superioridad, fatal!'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-10-08T00:00:00+00:00'::TIMESTAMPTZ, '7be3889372c67525d0d7cb03cf6b55a077f203887f5ca597bebc64a96293e398'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (553::BIGINT, 'Ojalá la vida la baje de esa nube, si realmente quiere aprender y son de aprendizaje activo, EVÍTELA'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-09-06T00:00:00+00:00'::TIMESTAMPTZ, 'aba223b1a70d89628c1f82d26a1672a70370a7ed6b590692a62699e5889afba0'::TEXT, ARRAY[613]::BIGINT[]),
    (553::BIGINT, 'Es buena persona, sus explicaciones son claras, quita pocos puntos en los informes y da mucho feedback. No le gusta la irresponsabilidad, llegue a tiempo, estudie las prácticas, SEA RESPETUOSO y participe. Con eso usted pasa al suave.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '5dd2872476131dd73ec33ed41bca6a514dfdc29b8f3175b29e9d683cec87bc26'::TEXT, ARRAY[567]::BIGINT[]),
    (553::BIGINT, 'Como profesora es bastante buena, se le entiende claro a sus indicaciones, mas de un par de veces demoraba con las evaluaciones. Como persona no es que le guste humillar, se ofrece a ayudar siempre, pero su personalidad es algo seca.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, '1f84c9184089550eabb4ca18cbb4df47c3173f286aaa2ff7dee2dad39186ff71'::TEXT, ARRAY[567]::BIGINT[]),
    (553::BIGINT, 'Pésima profesora, pésima persona. Tiene complejo de superioridad, trata horrible a todo mundo, cuando uno pregunta en vez de explicar regaña, y lo manda a preguntar a sus compañeros o a resolver usted. No de sorprendan si ven gente salir llorando. NO MATRICULEN, se van a arrepentir.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-05-29T00:00:00+00:00'::TIMESTAMPTZ, '0931d60006e8292ede54d50c256506ba80fd291207e2647d0ac1c840eb4412ce'::TEXT, ARRAY[567]::BIGINT[]),
    (553::BIGINT, 'Tiene una personalidad muy altiva y se cree muchísimo más que los estudiantes, la humildad en ella no existe y olvídese de que le ayudará, ella jamás ayuda y trata de tontos a los estudiantes y yo vi compañeras salir llorando por el trato que ella da, tiene un 0 rotundo como profesora y persona.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2024-02-12T00:00:00+00:00'::TIMESTAMPTZ, '02ac664cef47ff32f89ffef3a692804183ce0310c6daeeaf6390d47a26a35b8c'::TEXT, ARRAY[567]::BIGINT[]),
    (553::BIGINT, 'El ser más arrogante conocido'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2023-12-31T00:00:00+00:00'::TIMESTAMPTZ, '1254422c751033d2823d716efa2078a592f06bdb938a9da15726d0b23d912ca5'::TEXT, ARRAY[567]::BIGINT[]),
    (553::BIGINT, 'Es la peor profesora de lab, arrogante, un es un dolor para todo, cree que todo lo sabe y se hace la muy lista'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-15T00:00:00+00:00'::TIMESTAMPTZ, '1e5fb7baeb45c28ec5526676fa42f2892dfb3a522cc76295cceb6f3f7c318d79'::TEXT, ARRAY[567]::BIGINT[]),
    (553::BIGINT, 'Es demasiado odiosa, no ayuda con dudas, humilla demasiado a los estudiantes que van mal, no es nada accesible por si se necesita faltar, nunca matriculen con ella'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-11-10T00:00:00+00:00'::TIMESTAMPTZ, '233fa4d61c79444a7b68f0f06f3d8245897fd5211b557e346b6ec5c91fe50246'::TEXT, ARRAY[567]::BIGINT[]),
    (553::BIGINT, 'Es insoportable, nunca responde lo que le preguntan, siempre quiere pasarse de lista y termina viéndose 0 profesional. Califica según el humor en el que ande, las explicaciones no son muy buenas, dice exactamente lo que viene en el manual, 0 recomendada. Está obsesionada con que no la tuteen'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-10-19T00:00:00+00:00'::TIMESTAMPTZ, '7f31df5f68544b3e107ba1ee2359fd396201d4d032c2831c15aecd829175d310'::TEXT, ARRAY[613]::BIGINT[]),
    (553::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2023-09-08T00:00:00+00:00'::TIMESTAMPTZ, 'e0acd0681cd74db55b2f76010b3239b7a7d6c68652d3afcb78c228110574f536'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (553::BIGINT, 'La profe es súper linda y buena gente. Al iniciar la clase hace un repaso de lo que necesitamos saber para hacer la práctica. Da mucha retroalimentación en los informes y califica justo. Motiva mucho a sus estudiantes. Da puntillos extra para los quices en algunas clases. 100% recomendada.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'b6dbd704e8f8511903775c63a2ac4e74b9d83fd3a570c0871b00aad8fd536317'::TEXT, ARRAY[567]::BIGINT[]),
    (553::BIGINT, 'Buena profesora. Suele ser estricta con seguir todas las reglas al pie de la letra pero nada que le llegue a afectar. Califica suave en los exámenes e informes. Además, explica muy claro y sencillo lo práctico y teórico antes de iniciar la clase.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-20T00:00:00+00:00'::TIMESTAMPTZ, '34f25c2ef475ff6f30178ab849673574dadf137eee581ce0924ac15423bd0be4'::TEXT, ARRAY[567]::BIGINT[]),
    (553::BIGINT, 'La profe en sí es muy buena, explica bien y utiliza las 2 horas de clase. Además, deja los resumenes y la clase grabada para realizar los informes mejor. Califica bastante duro, pero uno suele acostumbrarse a como realizarlos acorde con lo que ella pide.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2022-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'f7fcbb0c9537d08514163a5efb7dc9b57598f47a8642a4df8c248c727812c0ea'::TEXT, ARRAY[613]::BIGINT[]),
    (553::BIGINT, 'Usa las dos horas de clase pero explica bien el experimento de cada semana, suele calificar un poco duro los informes pero nada de otro mundo, si participa en clase le da puntos.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases largas']::TEXT[], '2021-11-19T00:00:00+00:00'::TIMESTAMPTZ, '7e0ac7d76835471e3168d273c15908f34600235776286235d8ac2a26fefdf40a'::TEXT, ARRAY[613]::BIGINT[]),
    (553::BIGINT, 'La profe en si es buena, explica bien, los resúmenes que ella da son de gran ayuda, a veces si confunde bastante en temas fáciles. En las clases si uno preguntaba, respondía grosero y nos mandaba a leer el libro sin aclarar nada, al final ya teníamos miedo de preguntar.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-08-05T00:00:00+00:00'::TIMESTAMPTZ, 'd15952f038831d159b3655600909e70d5fe791470dee5647f48336590174e5fe'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Es una muy buena profe, explica claro y los resúmenes son de mucha ayuda. Les recomiendo que vayan a consulta y ahí ella les aclarará las dudas necesarias (yo lo hacía casi todas las semanas y no tuve un mal trato), pero en clase a veces tiende a molestarse cuando uno le pregunta.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'aefd0718dedf84cd0edbf8099274b2c8ad83f707987b1f447de4a7eb0162a0d5'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Si no lleva la meteria clara y al dia siempre, ni pregunte; ella tomara el tiempo para regañarlo envés de responderle al menos un sí o un no.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Clases largas']::TEXT[], '2021-07-12T00:00:00+00:00'::TIMESTAMPTZ, '24dd61dc967027fb26deb2fb9b50ced35dbcc010afcb23c37560c5447703f414'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Explica de la forma más técnica posible, no importa que el estudiante no entienda. Se enoja constantemente cuando se le hacen preguntas, y lo manda a leer o a ver la clase otra vez. Si es autodidacta se la puede jugar.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Clases largas']::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, 'f6ad3ac5c4c180297829b2aee3c51308b1d679c37e8eed03d367c60ed1d51466'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'No recomiendo para nada a esta profesora, francamente hasta miedo da hacer preguntas porque a veces está de buenas y a veces de malas, y en múltiples ocasiones cuando uno pregunta lo regaña, además incluso los temas fáciles los complica, evite matricular con ella a toda costa.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, '31681ed6f80740b1a3875ad9fe6bb18d161b847321047f617cdb7c75117e3427'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Sus clases son poco claras, no se le entiende nada incluso cuando es un tema fácil. Con ella hay que ser sumamente autodidacta porque de otra forma no se pasa el curso y cuando se le hacen consultas regaña por preguntar.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'f18a19ae5112b96f322ffa609f67c2784ba0c4c775ebe629be17d33b865eb3c5'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Al principio es buena. Después regaña cuando se hacen consultas. A veces se complica mucho explicando y no se entiende, incluso en temas fáciles.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'b8d51a8bab70df5edbf51c5ef05ff665c7d89e6fc088adebb9a985001b80366b'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'No aclara dudas, primero regaña y luego dice que la eso ya se debería saber. Las prácticas de clase no van acorde a sus evaluaciones.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2021-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'f14329f1c7106acda8931be877c56aa0821fb2700c122bcd7fe67e91e93819cf'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Esta profe parece que vive en una montaña rusa un día esta contenta y te resuelve las dudas, otro día esta que no se aguanta sola y te regaña hasta por respirar. Si encentran campo con Roldan matriculen con ella.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-17T00:00:00+00:00'::TIMESTAMPTZ, '0ef0998d56c66a554d7a3fb4f97459b78df5d24393e312cbbfcd8d107e546311'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'No es una mala profe, pero a veces cuando le preguntan algo primero regaña y dice que eso ya lo debería saber y luego procede a contestar. Las clases se hacen muy largas. Hace resúmenes que a veces ayudan y a veces son muy confusos porque no se entienden.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2021-06-15T00:00:00+00:00'::TIMESTAMPTZ, '8f55bf92c05e39d3eb6d7ffca165397c1ffd7d9e471a93ad1d9bc18a9b17b414'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Aura es un profe buena gente, pero a veces es algo odiosa, si se le pide ayuda sobre un tema dice que lo busque usted. Hace resúmenes durante las clases, a veces ayudan y a veces son larguísimos y nada claros. Las clases se hacen muy pesadas y largas.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '937cab1a701b976d90a396f103e692f1fea3c507cfa0d5349784b04a8a2b9c82'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'La profe no es tan mala, pero si uno le pregunta algo que no quedó claro le dice que eso está en los resúmenes o en la clase pasada, y los resúmenes no se entienden muy bien, es un poco molesta al contestar preguntas, las clases se hacen muy aburridas y definitivamente hay que buscar ayuda extra'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Clases largas']::TEXT[], '2021-06-09T00:00:00+00:00'::TIMESTAMPTZ, '1d80747f7887b2c1633859c3258ddf52f6feb950a7a049eb1b03f9b518b12988'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'La profesora es demasiado insoportable, muy impaciente. Si le pregunta algo en clase siempre dice que eso está en los resúmenes, los cuales son larguísimos y no se entiende nada.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2021-05-25T00:00:00+00:00'::TIMESTAMPTZ, 'c054ccaa6cc9e791360176eec17c56bdd212efb3ac1ab7bee8fc62b7457e0ebe'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Es muy buena, explica muy bien pero al rato ya es aburrido, se hacen muy largas las clases. Siempre está dispuesta a aclarar dudas y hace resúmenes en clases super buenos. Los quices son bastantes duros y hace quices sorpresa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'f691f84ecdfbf87624de878409eafd1347511beea773a54f9b02c1de8cdd7ef5'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, '575b9bb219d0bd76cb7e2b73021bcf65e7d5a8c87fae08d823313a60667f644f'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, '49340cfc3ae659f189f3a69c086ab5f58fd3c42662e6b7b6e457e8bf2dfa1959'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, '0bb19201a77f9f7dac47d7c9a949f3990ee3d0ddba064bdcdde2ea0a95af7780'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Se interesada porque sus estudiantes aprendan, aclara dudas super bien. Es muy amable y ama la materia. Hace resumenes en clase mientras explica. Sin duda matricule con ella. Es importante recibir las clases sincrónicas aunque son grabadas, debido a que premia con quices extras a los asistentes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2020-09-02T00:00:00+00:00'::TIMESTAMPTZ, 'f3dfe0248116188ab1aea2ac358369bcec5b6b79253424e3e359ae2489db4b88'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (553::BIGINT, 'Es el ser más insoportable como profesora, es muy desentendida, como coordinadora deja mucho que desear, ni siquiera saben enviar un correo sin hacer un spam horrible, molestan demasiados con las evaluaciones, a veces les importa más el que el estudiante no copie al hecho de que haga las cosas bien'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '942947e1d5acad853b08d118255ff61deef291e4df053a9a904aa49e78630e70'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Tiene una buena metodología de enseñanza, y le importa mucho que los estudiantes aprendan'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '412eaa798b721135a6406b9be96e8e023e2bcd34cb9138b6b74dbc85c11c6785'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (553::BIGINT, 'Excelente profesora, es muy ordenada con sus apuntes y se aprende mucho con ella. Las clases son muy entretenidas y aclara las dudas que uno tenga en cualquier momento. Se recomienda siempre el repaso constante de la materia para así no olvidar conceptos importantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'd8a6dcce1a48f4da5c1da14b649edb1ddc7279333223e440d2d99e3c712a4b3f'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'No le importa la situación del estudiante. Lo bueno es que hace resúmenes excelentes. Hace quices sorpresa'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '0c5b9a0adb122e94a90c32a0db09f4cac8d9843fea354752e6528194fb189325'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (553::BIGINT, 'Para las clases virtuales es muy cerrada y no le importó la situación del estudiante'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, '911f332504d59c4b322c89ea9d222dbb1e4f6c731375d8a2ca09c08d113e92a4'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'En modalidad virtual me pareció excelente, fue muy clara y los resúmenes que hace en clase ayuda a la hora de repasar la lección y durante los exámenes. La recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-31T00:00:00+00:00'::TIMESTAMPTZ, '89573fe47badb1e2b5fd64ceda73c758184c0b12549dda828da6c8f6a9d55928'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'La clase a veces se hace aburrida, si le caes bien, te ayuda, al que no, salado. Si le preguntas algo, algunas veces responde ahí y otras te dice que en hora de consulta (es malo si no puedes ir)'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, '875ff5a79da5fbc0d2f470af2d7feeb12be7da7cb830144223ccbfb25b5ce30a'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (553::BIGINT, 'Sus ejemplos son muy similares a los de los exámenes por lo que esto ayuda mucho.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '6a7a9c031d86af59d1f27ecacc195b03609dc482571c0223cd5c86da7079f81a'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Explica, en clase, lo suficiente para pasar los exámenes.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, '469b4752ed105aa7f1f34a139e5e694ff695abda592af3c32c30cdd96c97e149'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (553::BIGINT, 'Muy mala...'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '2e8ed2d31cdbba6e06ea90e3196f66091a153614c107e4cabce8493570182dd9'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Excelente profesora. Con lo que copia en la pizarra y las prácticas del folleto uno ya está listo para el examen. Los quices son complicados si uno no estudió. Se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'd184d18de168f9c7848c81c36658786c91441520de55e4b72bf84b25eb23c1d0'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'La materia la da de una manera muy ordenada y detallada, hace muchos ejemplos en clase y sabe bastante de la materia, por lo que aclara bien las dudas, es estricta pero muy buena, se aprende mucho en el curso, es de las mejores de la cátedra.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-04-08T00:00:00+00:00'::TIMESTAMPTZ, '972be13a1b10ca6cc438e259b18fc6dc29b844e456074fa455d5687d8f8ce895'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (553::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2017-06-16T00:00:00+00:00'::TIMESTAMPTZ, '5a82cdebc2758fd7e024001aa79819754d52739f6181b8e5db2445530c9893ec'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, '3c2c045dab24a19469b5b1b8b44ef2e5d00d6797b59832b65b16aca86e46ef8e'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Aura es una muy buena profe, super ordenada en la pizarra y tiene las clases bien planeadas siempre y ademas tiene como muchas ganas de enseñar. Lo unico malo es que copia y explica al mismo tiempo y aveces uno no sabe si copiar o poner atencion, pero es una excelente profesora, la recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-12-19T00:00:00+00:00'::TIMESTAMPTZ, '3eea73cb296e65d84b065eb96a13b09046b6337b489ca1397ca5af17534e7284'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Muy buena profe, explica y copia todo lo importante para el examen. Puede ser un poco odiosa a la hora de uno preguntar algo. Hay que estudiar para los quices son ejercicios de examen. La recomiendo prepara muy bien para los exámenes.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'cd69914e29048a8b591eaa70ca234e1ae58571ebc0495801c3d7292c19ef1bd6'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (553::BIGINT, 'Explica muy bien, lo necesario para el examen. Es MUY ODIOSA cuando se le pregunta algo, a menos que sea alguien que va súper bien o si le cae bien.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'a2b6942bdfee8898183736a30cd9b6114ea7b36c0fb3a1748a70bacbcdcc429c'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Es estricta y se puede estresar, pero en general es buena profe y da lo necesario para pasar (cuidado con los quices)'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-14T00:00:00+00:00'::TIMESTAMPTZ, '55e259e20d9cbbc43eb43518f4374c60980f2708cfa08d258a2927fbc2ea96b8'::TEXT, ARRAY[613]::BIGINT[]),
    (553::BIGINT, 'Muy Buena'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-19T00:00:00+00:00'::TIMESTAMPTZ, '1fcc2e293603dbf45a51dc8c992965f7fc4c43633e470f7c055c16628d992323'::TEXT, ARRAY[567]::BIGINT[]),
    (553::BIGINT, 'Tal vez en teoría sea buena pero en laboratorio es buena en cuanto a la enseñanza pero lo trata a uno como si uno no valiera nada ????'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, '373700ec94b3b3885cba46a63530d0101b8065dcdb5daa2a300225b377e116a3'::TEXT, ARRAY[567]::BIGINT[]),
    (553::BIGINT, 'La profesora Ledezma no es tan mala profesora, trata de atender todas las dudas, pero la manera en la que lo hace muchas veces no es la adecuada. Hay un tono de orgullo en su voz, no es muy empática.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '50e64cded522635b04615b4e06d598b2f4849b37ea091390b38e201eb455ebc2'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Excelente profe. Demasiado ordenada, explica bastante bien, es muy pura vida. Califica durillo, y los quices son rudos, pero si usted estudia le va bien, y sentirá fácil el examen.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'e21af166ce5bec747c4ebeb6ee4276e3548570976cf76cf7099f6240fa2b93b9'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Aura da la clase super ordenada (da como un paso a paso). Califica duro pero sin miedo puedes reclamar algún punto. Es muy comprensible y justa. Materia, una buena práctica y quiz. Se aprende mucho con ella.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '5a713ab6a95cdf12af11afba96491b1b94e6852d35e871ce06d0a8cd5d7ca260'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2016-05-25T00:00:00+00:00'::TIMESTAMPTZ, '07fbb526e5bcb26ef4869d8cccefac5f4fe40b4d5623722d6a0887873c5704d4'::TEXT, ARRAY[567]::BIGINT[]),
    (553::BIGINT, 'Muy buena profesora, es muy ordenada para dar la materia y da muchos ejemplos hay que estudiar para los quices y hacer las cosas como ella pide por que califica un poco duro'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-24T00:00:00+00:00'::TIMESTAMPTZ, '5f24d264a21d34ba824973523e384c347aad37e124c09ac4f03c0f79740e2b00'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Es muy buena gente con los estudiantes, va escribiendo un resumen de la materia mientras explica y es muy ordenada. Explica de forma clara. Los quices son un poco dificiles pero son parecidos al examen. Le gusta que los estudiantes vayan a consulta.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-19T00:00:00+00:00'::TIMESTAMPTZ, '54a1b4454b4482c5d5c990638eacd2c39dc25ee12722205435e94993d8135526'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Es muy ordenada para dar la materia y explica bien, pero los quices son lo peor y califica duro'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-13T00:00:00+00:00'::TIMESTAMPTZ, '2a18bd431f9e09afd11dbe9e3db495434d30c9d74e06ce6f9455b046a0c3a763'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (553::BIGINT, 'Es muy buena profe, se aprende bastante con ella, hay que poner mucha atención para estar copiando y a la vez entendiendo la materia. Es buena gente y muy accesible.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2015-07-24T00:00:00+00:00'::TIMESTAMPTZ, 'bb74b990c6f9e08d3ea1cf4b32ea86f52dcc4ca49653194685e8adabdc2f1350'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'ae19b4df3a046d25dcce592661d7ea451e47143116764307cac76f99d9cd3524'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'La prof Aura es muy buena gente pero la clase se me hace muy mala ya que copia toda la materia en la pizarra y uno tiene que ingeniársela para copiar, para poner atención y entender. Explica con mucho dos ejercicios un tema y continua rápidamente con el otro. Lo bueno es que hace muchos quices.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '4a32a112b2118e142272179bd3360a33ea40dc355ef719c631f5b9cedd3604a8'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'es super gentil, excepto con quienes hacen ruido en la clase. si uno se toma el tiempo de ir a consulta de seguro ella se toma el tiempo de hacer que ud le entienda, pero no espere pasar sin estudiar, porque a veces cuesta entenderle y que copia y explica al mismo tiempo.hay mejores pero se la juega'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'cc6077c4feb389716a1109c65a58704de7a7f1bae060c505777e71b462f77962'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Ella es muy gentil y te ayudará si tienes el tiempo de ir a consulta, se interesa por el estudiante, PERO: escribe y explica a la vez, por lo tanto vos debés escoger: o entendés o copiás. Muchos se han quedado por esto e ir a consulta no siempre es una opción.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, '0771a006adcfd728d68136671808bdc88fb8961aa2477606dee30cea296d3463'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'La materia la escribe en la pizarra, da buenos ejemplos, atiende las dudas que tengas, hace muchos quices y los califica de acuerdo a la materia! En fin, excelente para aquellos que se amoldan a su método en las clases! (lo más que pide es silencio es clase)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'b883cfcff9275577f4cd463264984cfe49affe641e218ad8424222f32b5fff3d'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Es muy dispuesta y enseña bien, pero a veces es un poco grosera'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-26T00:00:00+00:00'::TIMESTAMPTZ, '28cb8a9d6c9319e49e7f7be7f2f5e1a7e1aafb352516c40437961d252ab7f7cb'::TEXT, ARRAY[613]::BIGINT[]),
    (553::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-20T00:00:00+00:00'::TIMESTAMPTZ, '1275b990c0e8c12b65c90aab0efb06d6fd04e42bdf538ab0e2616fc36938c125'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'Una gran persona, pero no una excelente profe. Ella da el todo explicando y haciendo ejemplos, pero a muchas personas no les sirve el estilo en el que enseña. Lo bueno es que hace muchos quices y elimina los más bajos. Cubre toda la materia y aclara dudas. No es la mejor pero esta lejos de ser mala'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-19T00:00:00+00:00'::TIMESTAMPTZ, '20f5e57a6058ecf515785c2eda74bdf272efb55d5fa52fc49e89d92839a34029'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, '04ed11f2702677a8872802adfefe5e38974047bd72dcbbc5ab72398379281991'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Hace las clases aburridas y se desvía constantemente del tema. Evalúa bastantes quices acorde con el examen. Se aprende pero se debe tener paciencia.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-07T00:00:00+00:00'::TIMESTAMPTZ, '25accd94a838260f8b0ceef127cf86d8ecbb81471fbc1ffdc72f499c0d539980'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Explica muy claro,malos chistes,califica como debe de ser,enseña muy bien, quices muy duros,arrogante'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '4bff18dce66d2435c112676e7f81b169aa04110f588168add0cbec1b68ea22ad'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Siempre trata de ayudar y explica demasiado bien'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '051d6fcf2523a124b312d4390f5053cbbe1aef7d4c907b700e52d93e97ba2c96'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Hace los quices igual a como salen en el examen, califica normal, es simpatica, y la materia la da rapido asi que si no tienes buenas bases es mejor repasarlo pero si se entiende bastante.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-27T00:00:00+00:00'::TIMESTAMPTZ, '2c259fb01db3bdbea174cc689384d78a5a6b0f0d4bf16b7fb5fe727d3ee5f681'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Arrogante, juega de viva y antipática, su letra es muy pequeña y no se ve a larga distancia.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-25T00:00:00+00:00'::TIMESTAMPTZ, '1e375d7a029cc1fc7547b68892e10f1d5a9be6904fff82947accc5f19f12ddd8'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (553::BIGINT, 'Excelente profe y explica muy bien.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-02T00:00:00+00:00'::TIMESTAMPTZ, '84c6969fc8a42df680820d4275c093da40df7baf5cf4e3f418d6e2d4c9dbcf68'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (553::BIGINT, 'Es excelente profesora, califica algo fuerte, sin embargo, explica bastante bien, es muy ordenada para dar la materia y da muchas herramientas para practicar.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, '5497c8fa2537ba42221d8e10d1aa39ba7b35122da3f49f1a122dc20668837cde'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (553::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '9b45385e76221b53d2b7992fdf36d8d28221710a44bfcf5741297d1269615bfb'::TEXT, ARRAY[613]::BIGINT[]),
    (553::BIGINT, 'Excelente profesora. Explica la materia con mucha claridad y da muy buenas estrategias para resolver problemas. Sus quices son del mismo nivel del exámen. Tal vez es arrogante pero cuando preguntan algo que ella considera básico o que ya lo ha dicho. Es una de las mejores profes que he tenido!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'b13e12243a84c4f3b26faa2bd2434eead7beb43e7c92f1a9ebadae2b4a44dd35'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Explica bien, buena profesora.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '72211c66844bc1540252f57a021045c111ae0bae2a5a8d441b55649943fe881b'::TEXT, ARRAY[567, 613, 568, 614]::BIGINT[]),
    (553::BIGINT, 'Como profe es buena porque explica claro y repite, sin embargo, es un poco arrogante a la hora de contestar preguntas y ridiculiza mucho a la gente...No regala para nada el curso pero califica normal. Piendo que hay profes con más vocación que ella.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'bca8f58106b487950c8e5e977dc102c565184be3451500e9ce890a247dab798f'::TEXT, ARRAY[613]::BIGINT[]),
    (553::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-16T00:00:00+00:00'::TIMESTAMPTZ, '4262376622f57021b655bbe13688ce3b2127103c9954636a6668038262908998'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Es muy exigente, explica muy bien y se nota que quiere que los estudiantes aprendan y se interesen por el curso. Y como persona es super buena gente y le gusta que los estudiantes asistan a consulta.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '7e679090990b460fbb12e407e58471732a83db0a5f2db2d32c27d0c29f42aef8'::TEXT, ARRAY[3169, 3167]::BIGINT[]),
    (553::BIGINT, 'Ni fácil ni difícil, califica regular y explica bien. Se pasa el curso.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '4ffcc5c2823a6c8bff34dfa8adbc57efced999d40ba5701ba14b4e6dbda14424'::TEXT, ARRAY[614]::BIGINT[]),
    (553::BIGINT, 'La profesora en las clases de teoría es muy buena explica bastante claro y ayuda a los estudiantes, siempre motiva para que se vaya a consulta y hace muchos quices para eliminar los que posean las notas más bajas. En laboratorio es buena. Pero es mucho más estricta y le gusta las cosas en orden.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '940a00a912b85014188bbe4f70357fc85f4c7b377255296e6c293d613f658cb2'::TEXT, ARRAY[567, 613]::BIGINT[]),
    (553::BIGINT, 'La profesora Aura no es mala explicando (no es la mejor sin embargo), pero si se caracteriza por algo es por responder a las preguntas de los estudiantes con caras de cansancio, y explica la respuesta como si fuese la pregunta mas tonta hecha en la vida. Eso realmente lo desanima a uno.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '66cf99d2fb7fa4325054192c60c3ec7dcb7212a83858831f2358b3c3cfc523b8'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (553::BIGINT, 'Excelente profesora. Explica muy bien, preocupada por sus estudiantes. Califica un poco duro.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '2f0e65d85ff11ec6ad8c18ded27f2b9636ad9207a2f281dacff0a9eb3f6676e6'::TEXT, ARRAY[567, 613, 568, 614]::BIGINT[]),
    (553::BIGINT, 'Explica bien, la clase es bonita porque ella es simpática y se gana la clase.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '4f135fc27ce3796d22ae5e342f040ece526db3ab41cee3685bd1128ac6ecd1fc'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '1156942e4f127ca56a6f3b68bd3595d3c27b96deb349b9960b6bf6b3f05120e4'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '6f2fc04ed07bcec1f68a31d1adf74f5316adecc58a87e1a73a6301ad399ad37b'::TEXT, ARRAY[568]::BIGINT[]),
    (553::BIGINT, 'Para el lab se sufre un poco, pero al final si se puede pasar sin problemas.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'becd59feed871a8e108491af851a5b82be9d7619949bf9237b9db894579d97b3'::TEXT, ARRAY[613]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
